ENTRIES = {}
for line in DATA.strip().splitlines():
    word, pos, definition, chinese, example, pattern, related = line.split('|')
    key = word.lower()
    assert key not in ENTRIES, 'Repeated core word: ' + key
    ENTRIES[key] = dict(word=word, pos=pos, definition=definition, chinese=chinese,
                        example=example, pattern=pattern, related=related.split(';'))
